<script setup lang="ts">import {computed,inject,watchEffect} from 'vue';import {h0TabsKey,panelId,tabId} from './Tabs.context';import type {H0TabValue} from './Tabs.types';defineOptions({name:'H0TabPanel'});const props=defineProps<{value:H0TabValue}>();const context=inject(h0TabsKey)!;const active=computed(()=>context.active.value===props.value);watchEffect(()=>{if(active.value)context.visited.value.add(props.value)});const mounted=computed(()=>context.mountMode==='all'||active.value||(context.mountMode==='lazy'&&context.visited.value.has(props.value)))</script><template><div v-if="mounted" v-show="active" data-h0n-component="tab-panel" class="h-tab-panel" role="tabpanel" :id="panelId(context.baseId,value)" :aria-labelledby="tabId(context.baseId,value)" tabindex="0"><slot /></div></template><style scoped>.h-tab-panel{color:var(--h0n-ui-color-text);font-family:var(--h0n-ui-font-family);padding-block:var(--h0n-ui-spacing-lg)}.h-tab-panel:focus-visible{border-radius:var(--h0n-ui-radius-sm);box-shadow:var(--h0n-ui-focus-ring);outline:none}</style>
